<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Conway's Game of Life</title>
<style>
  :root {
    --bg: #07080d;
    --panel: #12141c;
    --ink: #e8ecf4;
    --muted: #8b93a7;
    --accent: #5eead4;
    --accent-2: #c084fc;
    --danger: #fb7185;
    --cell: #5eead4;
    --grid: #1c2030;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html, body {
    height: 100%;
    background:
      radial-gradient(900px 500px at 15% -10%, rgba(192,132,252,.18), transparent 50%),
      radial-gradient(800px 480px at 110% 10%, rgba(94,234,212,.12), transparent 45%),
      var(--bg);
    color: var(--ink);
    font-family: ui-sans-serif, system-ui, Segoe UI, Helvetica, Arial, sans-serif;
  }
  body {
    min-height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px 16px;
  }
  .wrap {
    width: min(720px, 100%);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 16px;
  }
  header {
    text-align: center;
    width: 100%;
  }
  h1 {
    font-size: 1.55rem;
    letter-spacing: .04em;
    font-weight: 750;
    background: linear-gradient(90deg, var(--accent), #a5b4fc, var(--accent-2));
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
  }
  .sub {
    margin-top: 6px;
    color: var(--muted);
    font-size: .9rem;
  }
  .stage {
    background: var(--panel);
    border: 1px solid #262a3a;
    border-radius: 18px;
    padding: 14px;
    box-shadow: 0 20px 60px rgba(0,0,0,.35), inset 0 1px 0 rgba(255,255,255,.04);
  }
  #life {
    display: block;
    width: 500px;
    height: 500px;
    max-width: calc(100vw - 64px);
    max-height: calc(100vw - 64px);
    background: #0b0d14;
    border-radius: 10px;
    cursor: crosshair;
    touch-action: none;
  }
  .controls {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    justify-content: center;
    width: 100%;
  }
  button {
    appearance: none;
    border: 1px solid #2a3144;
    background: linear-gradient(180deg, #1b2030, #141824);
    color: var(--ink);
    font: inherit;
    font-weight: 650;
    letter-spacing: .02em;
    padding: 10px 16px;
    border-radius: 999px;
    cursor: pointer;
    min-width: 104px;
    transition: transform .12s ease, border-color .12s ease, box-shadow .12s ease;
  }
  button:hover {
    transform: translateY(-1px);
    border-color: #4b5568;
    box-shadow: 0 8px 20px rgba(0,0,0,.25);
  }
  button:active { transform: translateY(0); }
  #step { border-color: #164e63; }
  #play { border-color: #134e4a; background: linear-gradient(180deg, #134e4a, #0f172a); }
  #play.running {
    background: linear-gradient(180deg, #7c3aed, #5b21b6);
    border-color: #c4b5fd;
  }
  #random { border-color: #5b21b6; }
  #clear { border-color: #7f1d1d; color: #fecdd3; }
  .meta {
    color: var(--muted);
    font-size: .82rem;
    display: flex;
    gap: 16px;
  }
  .meta b { color: var(--accent); font-weight: 700; }
</style>
</head>
<body>
  <div class="wrap">
    <header>
      <h1>✦ Petri Dish of Life</h1>
      <p class="sub">Paint cells, poke the universe, watch little critters wriggle.</p>
    </header>
    <div class="stage">
      <canvas id="life" width="500" height="500" aria-label="Game of Life grid"></canvas>
    </div>
    <div class="controls">
      <button id="step" type="button">Step ▸</button>
      <button id="play" type="button">Play ▶</button>
      <button id="random" type="button">Random ✨</button>
      <button id="clear" type="button">Clear</button>
    </div>
    <div class="meta">
      <span>gen <b id="gen">0</b></span>
      <span>alive <b id="pop">0</b></span>
      <span>B3/S23 · hard edges</span>
    </div>
  </div>
<script>
(function () {
  const W = 50;
  const H = 50;
  const canvas = document.getElementById('life');
  const ctx = canvas.getContext('2d');
  const genEl = document.getElementById('gen');
  const popEl = document.getElementById('pop');
  const playBtn = document.getElementById('play');

  let cells = new Uint8Array(W * H);
  let generation = 0;
  let playing = false;
  let timer = null;
  const INTERVAL = 110;

  function at(x, y) { return y * W + x; }

  function get(x, y) {
    if (x < 0 || y < 0 || x >= W || y >= H) return 0;
    return cells[at(x, y)] ? 1 : 0;
  }

  function set(x, y, v) {
    if (x < 0 || y < 0 || x >= W || y >= H) return;
    cells[at(x, y)] = v ? 1 : 0;
    draw();
  }

  function neighbors(x, y) {
    let n = 0;
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        n += get(x + dx, y + dy);
      }
    }
    return n;
  }

  function step() {
    const next = new Uint8Array(W * H);
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        const n = neighbors(x, y);
        const alive = cells[at(x, y)];
        next[at(x, y)] = (alive ? (n === 2 || n === 3) : n === 3) ? 1 : 0;
      }
    }
    cells = next;
    generation++;
    draw();
  }

  function clear() {
    cells.fill(0);
    generation = 0;
    draw();
  }

  function randomize() {
    for (let i = 0; i < cells.length; i++) cells[i] = Math.random() < 0.28 ? 1 : 0;
    generation = 0;
    draw();
  }

  function draw() {
    const cssW = canvas.clientWidth || 500;
    const cssH = canvas.clientHeight || 500;
    const dpr = Math.max(1, window.devicePixelRatio || 1);
    const pw = Math.round(cssW * dpr);
    const ph = Math.round(cssH * dpr);
    if (canvas.width !== pw || canvas.height !== ph) {
      canvas.width = pw;
      canvas.height = ph;
    }
    const cw = canvas.width / W;
    const ch = canvas.height / H;

    ctx.fillStyle = '#0b0d14';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.strokeStyle = 'rgba(38, 44, 64, 0.85)';
    ctx.lineWidth = Math.max(1, dpr * 0.6);
    ctx.beginPath();
    for (let x = 0; x <= W; x++) {
      ctx.moveTo(x * cw + 0.5, 0);
      ctx.lineTo(x * cw + 0.5, canvas.height);
    }
    for (let y = 0; y <= H; y++) {
      ctx.moveTo(0, y * ch + 0.5);
      ctx.lineTo(canvas.width, y * ch + 0.5);
    }
    ctx.stroke();

    let pop = 0;
    const pad = Math.max(1, cw * 0.12);
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        if (!cells[at(x, y)]) continue;
        pop++;
        const px = x * cw + pad;
        const py = y * ch + pad;
        const s = cw - pad * 2;
        const t = ch - pad * 2;
        const g = ctx.createLinearGradient(px, py, px + s, py + t);
        g.addColorStop(0, '#99f6e4');
        g.addColorStop(1, '#67e8f9');
        ctx.fillStyle = g;
        ctx.shadowColor = 'rgba(45, 212, 191, 0.85)';
        ctx.shadowBlur = 6 * dpr;
        ctx.fillRect(px, py, s, t);
      }
    }
    ctx.shadowBlur = 0;
    genEl.textContent = String(generation);
    popEl.textContent = String(pop);
  }

  function cellFromEvent(e) {
    const rect = canvas.getBoundingClientRect();
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const clientY = e.touches ? e.touches[0].clientY : e.clientY;
    const x = Math.floor((clientX - rect.left) / rect.width * W);
    const y = Math.floor((clientY - rect.top) / rect.height * H);
    return { x, y };
  }

  let painting = false;
  let paintValue = 1;
  let lastKey = '';

  function paintAt(e) {
    const { x, y } = cellFromEvent(e);
    const key = x + ',' + y;
    if (key === lastKey) return;
    lastKey = key;
    set(x, y, paintValue);
  }

  canvas.addEventListener('mousedown', function (e) {
    e.preventDefault();
    painting = true;
    lastKey = '';
    const { x, y } = cellFromEvent(e);
    paintValue = get(x, y) ? 0 : 1;
    set(x, y, paintValue);
    lastKey = x + ',' + y;
  });
  window.addEventListener('mousemove', function (e) {
    if (!painting) return;
    paintAt(e);
  });
  window.addEventListener('mouseup', function () {
    painting = false;
    lastKey = '';
  });
  canvas.addEventListener('touchstart', function (e) {
    e.preventDefault();
    painting = true;
    lastKey = '';
    const { x, y } = cellFromEvent(e);
    paintValue = get(x, y) ? 0 : 1;
    set(x, y, paintValue);
    lastKey = x + ',' + y;
  }, { passive: false });
  canvas.addEventListener('touchmove', function (e) {
    e.preventDefault();
    if (!painting) return;
    paintAt(e);
  }, { passive: false });
  window.addEventListener('touchend', function () {
    painting = false;
    lastKey = '';
  });

  function setPlaying(on) {
    playing = on;
    playBtn.classList.toggle('running', playing);
    playBtn.textContent = playing ? 'Pause ⏸' : 'Play ▶';
    if (timer) {
      clearInterval(timer);
      timer = null;
    }
    if (playing) timer = setInterval(step, INTERVAL);
  }

  document.getElementById('step').addEventListener('click', function () {
    setPlaying(false);
    step();
  });
  playBtn.addEventListener('click', function () { setPlaying(!playing); });
  document.getElementById('random').addEventListener('click', function () {
    randomize();
  });
  document.getElementById('clear').addEventListener('click', function () {
    setPlaying(false);
    clear();
  });

  window.addEventListener('resize', draw);

  window.life = {
    w: W,
    h: H,
    get: get,
    set: set,
    step: step,
    clear: clear
  };

  draw();
})();
</script>
</body>
</html>
